//! Bounded actual-viewport map loading and explicit navigation; no area prefetch.
use crate::{*,serde_json::{json,Value}};
pub fn controller(input:Value,provider:Value)->Value{controller_with_routes(input,provider,None,None)}
pub fn controller_with_routes(input:Value,provider:Value,geocoder:Option<&maps_geo::Provider>,router:Option<&maps_geo::Provider>)->Value{let mut s=input["state"].clone();if !s.is_object()||s["provider"]!=provider{s=json!({"provider":provider,"latitude":"","longitude":"","zoom":"2","map":null,"status":"Choose a center","open":false,"width":0,"height":0,"queue":[],"loading":false,"query":"","controls":false,"places":null,"route_from":null});}let e=&input["event"];let a=e["action"].as_str().unwrap_or("");let ok=e["reply"]["ok"]==true;let v=&e["reply"]["value"];let mut req=Value::Null;
match a{
"map.controls"=>s["controls"]=json!(true),"map.controls.close"=>s["controls"]=json!(false),
"map.latitude"|"map.longitude"|"map.zoom"|"map.query"=>s[&a[4..]]=e["value"].clone(),"map.back"=>{s["open"]=json!(false);s["queue"]=json!([]);},
"map.open"=>{let result=(||{let lat=s["latitude"].as_str().and_then(|v|v.trim().parse::<f64>().ok()).ok_or("Enter latitude")?;let lon=s["longitude"].as_str().and_then(|v|v.trim().parse::<f64>().ok()).ok_or("Enter longitude")?;let zoom=s["zoom"].as_str().and_then(|v|v.trim().parse::<u8>().ok()).filter(|z|*z<=19).ok_or("Enter zoom0–19")?;if !lat.is_finite()||!lon.is_finite()||lat.abs()>85.05112878||lon.abs()>180.{return Err("Center is outside supported map area")}let(x,y)=maps::project(lat,lon,zoom).map_err(|_|"Invalid map zoom")?;s["map"]=maps::viewer("map.preview",s["provider"].clone(),lat,lon,zoom,vec![],vec![]);s["x"]=json!(x.floor()as u32);s["y"]=json!((y.floor()as u32).min((1u32<<zoom)-1));s["open"]=json!(true);s["queue"]=json!([]);Ok(())})();if let Err(err)=result{s["status"]=json!(err);}},
"map.viewport"=>{s["width"]=e["value"]["width"].clone();s["height"]=e["value"]["height"].clone();let op=e["value"]["operation"].as_str().unwrap_or("viewport");if op!="viewport"{let z=s["map"]["zoom"].as_u64().unwrap_or(0)as u8;let lat=s["map"]["latitude"].as_f64().unwrap_or(0.);let lon=s["map"]["longitude"].as_f64().unwrap_or(0.);let(x,y)=maps::project(lat,lon,z).unwrap_or((0.,0.));let(dx,dy)=match op{"north"=>(0.,-0.5),"south"=>(0.,0.5),"west"=>(-0.5,0.),"east"=>(0.5,0.),"pan"=>(e["value"]["dx"].as_f64().filter(|v|v.is_finite()).unwrap_or(0.).clamp(-4.,4.),e["value"]["dy"].as_f64().filter(|v|v.is_finite()).unwrap_or(0.).clamp(-4.,4.)),_=>(0.,0.)};let(lat,lon)=maps::unproject(x+dx,y+dy,z).unwrap_or((lat,lon));let nz=match op{"zoom_in"=>(z+1).min(19),"zoom_out"=>z.saturating_sub(1),_=>z};s["map"]["latitude"]=json!(lat);s["map"]["longitude"]=json!(lon);s["map"]["zoom"]=json!(nz);s["latitude"]=json!(format!("{lat:.6}"));s["longitude"]=json!(format!("{lon:.6}"));s["zoom"]=json!(nz.to_string());if nz!=z{s["map"]["tiles"]=json!([]);}s["status"]=json!("View moved; load visible tiles for fresh coverage");}},
"map.load"|"map.offline"=>{if s["width"].as_u64().unwrap_or(0)>0&&s["height"].as_u64().unwrap_or(0)>0{req=maps::viewport(&s["map"],s["width"].as_u64().unwrap()as u32,s["height"].as_u64().unwrap()as u32,a=="map.offline","map.coverage");s["loading"]=json!(true);s["controls"]=json!(false);}else{s["status"]=json!("Waiting for the native map viewport size");}},
"map.coverage" if ok=>{s["queue"]=json!([]);s["new_tiles"]=json!([]);let mut stale=false;let mut missing=0;for row in v["tiles"].as_array().into_iter().flatten(){if row["value"]["hit"]==true{s["new_tiles"].as_array_mut().unwrap().push(maps::tile(row["x"].as_u64().unwrap()as u32,row["y"].as_u64().unwrap()as u32,row["value"]["file"].as_str().unwrap()));stale|=row["value"]["stale"]==true;}else if row["value"]["request"].is_object(){s["queue"].as_array_mut().unwrap().push(row.clone());}else{missing+=1}}s["coverage_stale"]=json!(stale);s["coverage_missing"]=json!(missing);s["map"]["tiles"]=s["new_tiles"].clone();s["status"]=json!(if stale{"Saved tiles are stale"}else if missing>0{"Offline coverage is incomplete"}else{"Loading visible map coverage"});req=next(&mut s);},
"map.fetched" if ok=>req=maps::cache_response(&s["map"],s["current"]["x"].as_u64().unwrap()as u32,s["current"]["y"].as_u64().unwrap()as u32,v.clone(),"map.stored"),
"map.stored" if ok=>{if v["stored"]==true{let tile=maps::tile(s["current"]["x"].as_u64().unwrap()as u32,s["current"]["y"].as_u64().unwrap()as u32,v["file"].as_str().unwrap());s["map"]["tiles"].as_array_mut().unwrap().push(tile);if v["stale"]==true{s["coverage_stale"]=json!(true)}}else{s["coverage_missing"]=json!(s["coverage_missing"].as_u64().unwrap_or(0)+1);s["status"]=json!("Some visible tiles cannot be cached by provider policy");}req=next(&mut s);},
"map.north"|"map.south"|"map.west"|"map.east"|"map.zoom_in"|"map.zoom_out"=>{if let Some(z)=s["map"]["zoom"].as_u64(){let lat=s["map"]["latitude"].as_f64().unwrap();let lon=s["map"]["longitude"].as_f64().unwrap();let(x,y)=maps::project(lat,lon,z as u8).unwrap();let(dx,dy)=match a{"map.north"=>(0.,-1.),"map.south"=>(0.,1.),"map.west"=>(-1.,0.),"map.east"=>(1.,0.),_=>(0.,0.)};let(lat,lon)=maps::unproject(x+dx,y+dy,z as u8).unwrap();let nz=match a{"map.zoom_in"=>(z+1).min(19),"map.zoom_out"=>z.saturating_sub(1),_=>z};s["controls"]=json!(false);s["map"]["latitude"]=json!(lat);s["map"]["longitude"]=json!(lon);s["map"]["zoom"]=json!(nz);s["map"]["tiles"]=json!([]);s["status"]=json!("View changed; load visible tiles");}},
"map.search"=>if let Some(p)=geocoder{match maps_geo::search(p,s["query"].as_str().unwrap_or(""),"map.places"){Ok(r)=>req=r,Err(e)=>s["status"]=json!(e)}},
"map.places" if ok=>if let Some(p)=geocoder{match maps_geo::places(p,v){Ok(r)=>{s["places"]=r;s["controls"]=json!(true)},Err(e)=>s["status"]=json!(e)}},
_ if a.starts_with("map.pick.")=>{if let Some(place)=a[9..].parse::<usize>().ok().and_then(|i|s["places"]["items"].as_array().and_then(|a|a.get(i))).cloned(){s["controls"]=json!(false);s["map"]["latitude"]=place["latitude"].clone();s["map"]["longitude"]=place["longitude"].clone();s["map"]["tiles"]=json!([]);s["status"]=json!("Selected place; load visible tiles");}},
"map.route.start"=>s["route_from"]=json!([s["map"]["latitude"],s["map"]["longitude"]]),
"map.route.to"=>if let(Some(p),Some(lat),Some(lon))=(router,s["route_from"][0].as_f64(),s["route_from"][1].as_f64()){match maps_geo::route(p,"driving",&[(lat,lon),(s["map"]["latitude"].as_f64().unwrap(),s["map"]["longitude"].as_f64().unwrap())],"map.routed"){Ok(r)=>req=r,Err(e)=>s["status"]=json!(e)}},
"map.routed" if ok=>if let Some(p)=router{match maps_geo::route_result(p,v).and_then(|r|{s["status"]=json!(format!("Route {:.1} km · {:.0} min",r["distance_m"].as_f64().unwrap()/1000.,r["duration_s"].as_f64().unwrap()/60.));maps_geo::with_route(s["map"].clone(),&r)}){Ok(map)=>s["map"]=map,Err(e)=>s["status"]=json!(e)}},_=>{}}
if e["reply"]["ok"]==false{s["loading"]=json!(false);s["queue"]=json!([]);s["status"]=json!("Request unavailable/access denied; visible results retained. Retry explicitly.");}
if s["open"]==true{s["map"]["on_viewport"]=json!("map.viewport");s["map"]["viewport_width"]=s["width"].clone();s["map"]["viewport_height"]=s["height"].clone();let enabled=s["loading"]!=true;let mut actions=vec![button("map.load","Load visible tiles").enabled(enabled),button("map.offline","Offline cache").enabled(enabled&&s["provider"]["offline_allowed"]==true)];for(a,t)in[("north","North"),("south","South"),("west","West"),("east","East"),("zoom_in","Data zoom +"),("zoom_out","Data zoom −")]{actions.push(button(&format!("map.{a}"),t).enabled(enabled));}if router.is_some(){actions.push(button("map.route.start","Route start here"));actions.push(button("map.route.to","Route to center"));}let mut drawer=Vec::new();if geocoder.is_some(){drawer.push(field("map.query","Search places",s["query"].as_str().unwrap_or("")));drawer.push(button("map.search","Find place"));if s["places"].is_object(){drawer.extend(maps_geo::place_rows(&s["places"],"map.pick"));}}let navigation=actions.split_off(2);drawer.extend(navigation);let mut body=vec![label("map.status",s["status"].as_str().unwrap_or(""))];for n in actions{body.push(n.row("map.load.row"));}body.push(button("map.controls","Map controls / routes").row("map.load.row"));body.push(s["map"].clone());let mut screen=Screen::new("Map",s.clone()).body(body).back("map.back").effect(req);if s["controls"]==true{screen=screen.drawer("Map controls","map.controls.close",drawer);}return screen.finish()}

Screen::new("Map",s.clone()).body(vec![field("map.latitude","Latitude",s["latitude"].as_str().unwrap_or("")),field("map.longitude","Longitude",s["longitude"].as_str().unwrap_or("")),field("map.zoom","Data zoom0–19",s["zoom"].as_str().unwrap_or("2")),label("map.status",s["status"].as_str().unwrap_or("")),button("map.open","Open map")]).scrollable().effect(req).finish()}
fn next(s:&mut Value)->Value{if !s["queue"].as_array().is_some_and(|q|!q.is_empty()){s["loading"]=json!(false);s["status"]=json!(format!("{} visible tiles loaded{}{}",s["map"]["tiles"].as_array().map_or(0,Vec::len),if s["coverage_stale"]==true{" · saved data is stale"}else{""},if s["coverage_missing"].as_u64().unwrap_or(0)>0{" · coverage incomplete"}else{""}));return Value::Null}let row=s["queue"].as_array_mut().unwrap().remove(0);s["current"]=row.clone();maps::fetch_cached_request(&row["value"],"map.fetched").unwrap_or(Value::Null)}
